window.docContents[194].resolve({"/#Jakarta-Persistence":{"contents":"This book models how construction and lifecycle operations affect an entity's\nstate and persistent identity in one persistence context. Sections 2.1 and 2.4\nintroduce entity instances and identity. Selected parts of section 3.6 pair\nthe lifecycle rules with checked Lean/Veil code. The proofs, finite regression\nchecks, and proof trust audit follow.\n\nFormalized SpecificationThe numbered sections are excerpts from Jakarta Persistence 4.0-M4\n(May 25, 2026, DRAFT), authored by the Jakarta Persistence Team. Each excerpt keeps\nits original section number.\nBlocks labelled Formalized Specification contain the project's explanations\nand checked Lean code.Copyright (c) 2019, 2024 Eclipse Foundation.\nCopyright (c) 2026 Eclipse Foundation AISBL. This software or document includes\nmaterial copied from or derived from Jakarta Persistence 4.0-M4.\nThe complete Eclipse Foundation Specification License v1.1 appears at the end of the book.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Jakarta Persistence","id":"/#Jakarta-Persistence"}});